/**
 * Pre-recorded neural voice clips (Azure AI Speech, generated by scripts/gen-voice.ts).
 *
 * public/audio/manifest.json maps "<voice>|<speed>|<text>" to an mp3 file. speak() asks here first;
 * when a clip exists it is played with an <audio> element, otherwise the device voice is used.
 *   voice: 'pl-f' (Zofia, the teacher), 'pl-m' (Marek), 'he' (Hila), 'en' (Jenny)
 *   speed: 'n' normal, 's' slow (synthesized slowly – not a sped-down copy)
 * The standalone single-file build has no audio folder, so it streams from the live site.
 */

import { isStandaloneBuild } from './env';

export type ClipVoice = 'pl-f' | 'pl-m' | 'he' | 'en';
export type ClipSpeed = 'n' | 's';

export interface ClipManifest {
  version: number;
  voices: Record<ClipVoice, string>;
  clips: Record<string, string>;
}

const LIVE_AUDIO = 'https://hanan87.github.io/polish-learn-app/audio/';
export const AUDIO_BASE = isStandaloneBuild ? LIVE_AUDIO : `${import.meta.env?.BASE_URL ?? '/'}audio/`;
const PREF_KEY = 'polish-learn:natural-voice';

/** Canonical form of a phrase for lookup: Unicode NFC, single spaces, trimmed. */
export function clipText(text: string): string {
  return text.normalize('NFC').replace(/\s+/g, ' ').trim();
}

export function clipKey(voice: ClipVoice, speed: ClipSpeed, text: string): string {
  return `${voice}|${speed}|${clipText(text)}`;
}

let manifest: ClipManifest | null = null;
let loading: Promise<ClipManifest | null> | null = null;
const listeners = new Set<() => void>();

export function setManifest(m: ClipManifest | null): void {
  manifest = m;
  listeners.forEach((l) => l());
}

export function getManifest(): ClipManifest | null {
  return manifest;
}

export function subscribeManifest(fn: () => void): () => void {
  listeners.add(fn);
  return () => listeners.delete(fn);
}

export function loadManifest(): Promise<ClipManifest | null> {
  if (manifest) return Promise.resolve(manifest);
  if (loading) return loading;
  if (typeof fetch === 'undefined') return Promise.resolve(null);
  loading = fetch(`${AUDIO_BASE}manifest.json`, { cache: 'no-cache' })
    .then((r) => (r.ok ? (r.json() as Promise<ClipManifest>) : null))
    .then((m) => {
      if (m && m.clips) setManifest(m);
      return manifest;
    })
    .catch(() => null)
    .finally(() => {
      loading = null;
    });
  return loading;
}

/** Learner preference: natural recorded voice (default) or the device voice only. */
export function naturalVoiceEnabled(): boolean {
  try {
    return localStorage.getItem(PREF_KEY) !== 'off';
  } catch {
    return true;
  }
}

export function setNaturalVoiceEnabled(on: boolean): void {
  try {
    localStorage.setItem(PREF_KEY, on ? 'on' : 'off');
  } catch {
    // Storage disabled: the choice lasts for this session only.
  }
  listeners.forEach((l) => l());
}

/**
 * Best clip for a phrase. Preference order: requested voice → the other Polish voice (Polish only).
 * Returns the full URL or null.
 */
export function findClip(text: string, speed: ClipSpeed, voice: ClipVoice = 'pl-f'): string | null {
  if (!manifest || !naturalVoiceEnabled()) return null;
  const order: ClipVoice[] = voice === 'pl-m' ? ['pl-m', 'pl-f'] : voice === 'pl-f' ? ['pl-f', 'pl-m'] : [voice];
  // Single words are also recorded without punctuation ("mlekiem." → "mlekiem").
  const bare = text.replace(/^[^\p{L}]+|[^\p{L}]+$/gu, '');
  for (const t of bare && bare !== text.trim() && !/\s/.test(bare) ? [text, bare] : [text]) {
    for (const v of order) {
      const file = manifest.clips[clipKey(v, speed, t)];
      if (file) return AUDIO_BASE + file;
    }
  }
  return null;
}

export function clipCount(): number {
  return manifest ? Object.keys(manifest.clips).length : 0;
}

// --- playback -------------------------------------------------------------------------------

let audioEl: HTMLAudioElement | null = null;
let stopCurrent: (() => void) | null = null;

function element(): HTMLAudioElement {
  // One element for the whole app: once a tap has started it, iOS allows later programmatic plays.
  if (!audioEl) {
    audioEl = new Audio();
    audioEl.preload = 'auto';
  }
  return audioEl;
}

export function clipPlaying(): boolean {
  return !!audioEl && !audioEl.paused && !audioEl.ended;
}

export function stopClip(): void {
  stopCurrent?.();
  stopCurrent = null;
  if (audioEl && !audioEl.paused) audioEl.pause();
}

/**
 * Play a clip. Resolves true when it played to the end (or was stopped), false when it could not
 * play at all – the caller then falls back to the device voice.
 */
export function playClip(url: string, playbackRate = 1): Promise<boolean> {
  stopClip();
  const el = element();
  return new Promise((resolve) => {
    let settled = false;
    let started = false;
    const finish = (ok: boolean) => {
      if (settled) return;
      settled = true;
      el.onended = null;
      el.onerror = null;
      el.onplaying = null;
      clearTimeout(guard);
      if (stopCurrent === cancel) stopCurrent = null;
      resolve(ok);
    };
    const cancel = () => finish(true);
    stopCurrent = cancel;
    // If nothing starts within 6 s (offline, blocked autoplay) give up and let the device voice speak.
    const guard = window.setTimeout(() => finish(started), 6000);
    el.onended = () => finish(true);
    el.onerror = () => finish(started);
    el.onplaying = () => {
      started = true;
      clearTimeout(guard);
    };
    el.src = url;
    el.playbackRate = playbackRate;
    (el as HTMLAudioElement & { preservesPitch?: boolean }).preservesPitch = true;
    el.play().catch(() => finish(false));
  });
}

/** Download every clip into the offline cache (service worker runtime cache). */
export async function cacheAllClips(onProgress?: (done: number, total: number) => void): Promise<number> {
  const m = manifest ?? (await loadManifest());
  if (!m || typeof caches === 'undefined') return 0;
  const files = [...new Set(Object.values(m.clips))];
  const cache = await caches.open('voice-clips');
  let done = 0;
  const queue = [...files];
  const worker = async () => {
    while (queue.length) {
      const f = queue.shift()!;
      const url = AUDIO_BASE + f;
      if (!(await cache.match(url))) {
        try {
          const res = await fetch(url);
          if (res.ok) await cache.put(url, res);
        } catch {
          // Keep going: a missing clip just falls back to the device voice.
        }
      }
      done++;
      onProgress?.(done, files.length);
    }
  };
  await Promise.all([worker(), worker(), worker(), worker()]);
  return done;
}
